const dayOf = s => (Date.UTC(+s.slice(0,4), +s.slice(5,7)-1, +s.slice(8,10)) - D0)/864e5;
const dstr = d => { const t=new Date(D0+d*864e5); return String(t.getUTCDate()).padStart(2,"0")+"-"+String(t.getUTCMonth()+1).padStart(2,"0")+"-"+t.getUTCFullYear(); };
const mOf = d => new Date(D0+d*864e5).getUTCMonth();
const hhmm = m => m==null ? "" : String(Math.floor(m/60)%24).padStart(2,"0")+":"+String(m%60).padStart(2,"0");

const AREA_COL = {"Area Mendis":"#38bdf8","Area B 80":"#a3e635","Area Pakerin":"#fb923c","Area Selaro":"#f472b6","Area ISP":"#facc15","Area Dayung":"#2dd4bf","Area Bintialo":"#c084fc","Area Ketapat":"#f87171","Area Mekar Sari":"#60a5fa"};
/* warna tipe & route = Dashboard Loss Time */
const TCOL = {R:"#2a78d6",S:"#5bb8e8",A:"#d03b3b",E:"#e0842a",M:"#8b5cf6",T:"#f2b632",NH:"#94a3b8",CP:"#e2559b",D:"#a47148",SI:"#14b8a6",FM:"#64748b",MC:"#5b4bd6",RG:"#7fb13a",WB:"#0891b2"};
const RCOL = {H1:"var(--s1)", ISP:"var(--s2)", H2:"var(--s3)"};
const MMJ_CODES = new Set(["T","A","E","M","D","WB"]);      /* Technical, Traffic, Dust, Weigh Bridge; selain itu Bukan MMJ */
const PAL_LT = ["#fef3c7","#fcd34d","#f59e0b","#ea580c","#b91c1c"];     /* kuning -> merah: jam loss time */
/* kelas tetap warna loss time per ruas (user 2026-11-28): [batas atas, warna, label]; 0 jam = abu-abu */
const LT_KLS = [[1,"#fde68a","&lt; 1 jam",true],[2.5,"#f59e0b","1 – 2,5 jam"],[5,"#ea580c","2,5 – 5 jam"],[Infinity,"#b91c1c","&gt; 5 jam"]];
const ltCol = v => { for(const k of LT_KLS){ if(k[3] ? v < k[0] : v <= k[0]) return k[1]; } return LT_KLS[LT_KLS.length-1][1]; };
const PAL_RN = ["#e0f2fe","#7dd3fc","#38bdf8","#2563eb","#1e3a8a"];     /* biru muda -> biru tua: curah hujan */
const NODATA = "#94a3b8";

const TY = P.types, TC = TY.map(t=>t.c), TN = TY.map(t=>t.n), NT = TY.length;
const R = P.lt.rows;                    /* [hari, route, tipe, km*10, jam*100, t2, desc, dari(menit), sampai(menit), area] */
const RAIN = P.rain;                    /* [hari, pos, mm*10, jam*100, dari, sampai] */
const POS = P.pos;
const KMT = P.geo.kmt, KMAX = P.geo.total;
const SEGK = Object.keys(P.seg).map(Number).sort((a,b)=>a-b), SEGMAX = SEGK[SEGK.length-1];
function kmLL(x){ const t = Math.max(0, Math.min(KMT.length-1, x*10)), a = Math.floor(t), b = Math.min(KMT.length-1, a+1), f = t-a; const p = KMT[a], q = KMT[b]; return [p[0]+(q[0]-p[0])*f, p[1]+(q[1]-p[1])*f]; }
const BL = () => P.fleets[st.fleet] || P.fleets["14"];
const blokOf = km => { const bl = BL(); for(const b of bl) if(km>=b[0] && km<b[1]) return b; return km<0 ? bl[0] : bl[bl.length-1]; };
const segOf = km10 => Math.max(0, Math.min(SEGMAX, Math.floor(km10/10)));

