P.geo.marks.forEach(m=>{ const c = MKC[m.k]; if(!c) return;
  const html = m.lbl ? `<span class="mki big" style="background:${c.c}">${MKI[c.k]}<em>${esc(m.lbl)}</em></span>` : `<span class="mki" style="background:${c.c}">${MKI[c.k]}</span>`;
  L.marker(m.ll, {title:m.n, zIndexOffset:m.lbl?900:0, icon:L.divIcon({className:"", iconSize:[0,0], html})})
   .bindTooltip(`<b>${esc(m.n)}</b><br><span style="color:var(--muted)">${esc(c.n)}${m.km!=null?` · KM ${fmt(m.km,m.km%1?2:0)}`:""}${m.dia?` · diameter ${esc(m.dia)}`:""}${m.rute?` · ${esc(m.rute)}`:""}${m.area?` · ${esc(m.area)}`:""}</span>`, {direction:"top", offset:[0,-12]}).addTo(mkLayer[c.k]); });
