$("#fMark").innerHTML = P.markKelas.map(k=>{ const n = P.geo.marks.filter(m=>m.k===k.k).length; return n ? `<button class="tchip mchip" type="button" data-v="${k.k}" title="${esc(k.n)}: ${n} titik"><span class="ico" style="background:${k.c}">${MKI[k.k]}</span><span class="tn">${esc(k.n)}</span><span class="cnt">${n}</span></button>` : ""; }).join("");
on("#fMark","click",e=>{ const b=e.target.closest("button"); if(!b) return; st.mk[b.dataset.v] = st.mk[b.dataset.v] ? 0 : 1; render(); });
